  2	using System.Collections.ObjectModel;
  3	using System.ComponentModel;
  4	using LoadOrderKeeper.Models;
  5	using LoadOrderKeeper.Tests.Fixtures;
  6	using LoadOrderKeeper.ViewModels;
  7	using Xunit;
  8	
  9	namespace LoadOrderKeeper.Tests.ViewModels;
 10	
 11	/// <summary>
 12	/// Unit tests for the computed guidance-sidebar properties added to
 13	/// <see cref="DiffDialogViewModel"/> in WP-004, and for the confirmation-message
 14	/// builder extracted in WP-001 of the rework plan.
 15	/// </summary>
 16	/// <remarks>
 17	/// All tests use the <c>internal</c> test-only constructor that accepts a
 18	/// pre-populated <see cref="ObservableCollection{T}"/> of <see cref="DiffLineModel"/>
 19	/// objects and skips the full coordinator/MainViewModel dependency graph.
 20	/// <see cref="DiffDialogViewModel.BuildConfirmationMessage"/> is <c>internal</c>
 21	/// and accessible via the <c>InternalsVisibleTo</c> attribute declared in the main
 22	/// project file.
 23	/// </remarks>
 24	[Collection(LocaleSequentialCollection.Name)]
 25	public sealed class DiffDialogViewModelTests : IClassFixture<EnglishLocaleFixture>
 26	{
 27	    public DiffDialogViewModelTests(EnglishLocaleFixture localeFixture)
 28	    {
 29	        _ = localeFixture; // Ensures en-US locale is active for all tests in this class
 30	    }
 31	
 32	    // ── Helpers ─────────────────────────────────────────────────────────────────
 33	
 34	    private static DiffLineModel Line(DiffChangeType changeType, string name = "Mod.esm") =>
 35	        new(name, name, changeType, referenceNumber: 1, currentNumber: 1);
 36	
 37	    private static DiffDialogViewModel Create(IEnumerable<DiffLineModel> lines) =>
 38	        new(new ObservableCollection<DiffLineModel>(lines));
 39	
 40	    // ── ShowRemovalGuidance ──────────────────────────────────────────────────────
 41	
 42	    [Fact]
 43	    public void ShowRemovalGuidance_WhenRemovedModsPresent_ReturnsTrue()
 44	    {
 45	        // Arrange
 46	        var vm = Create([Line(DiffChangeType.Removed)]);
 47	
 48	        // Act & Assert
 49	        Assert.True(vm.ShowRemovalGuidance);
 50	    }
 51	
 52	    [Fact]
 53	    public void ShowRemovalGuidance_WhenNoRemovedMods_ReturnsFalse()
 54	    {
 55	        // Arrange: only safe changes
 56	        var vm = Create([Line(DiffChangeType.Added)]);
 57	
 58	        // Act & Assert
 59	        Assert.False(vm.ShowRemovalGuidance);
 60	    }
 61	
 62	    // ── ShowInsertionGuidance ────────────────────────────────────────────────────
 63	
 64	    [Fact]
 65	    public void ShowInsertionGuidance_WhenInsertedModsPresent_ReturnsTrue()
 66	    {
 67	        // Arrange
 68	        var vm = Create([Line(DiffChangeType.Inserted)]);
 69	
 70	        // Act & Assert
 71	        Assert.True(vm.ShowInsertionGuidance);
 72	    }
 73	
 74	    [Fact]
 75	    public void ShowInsertionGuidance_WhenNoInsertedMods_ReturnsFalse()
 76	    {
 77	        // Arrange
 78	        var vm = Create([Line(DiffChangeType.Added)]);
 79	
 80	        // Act & Assert
 81	        Assert.False(vm.ShowInsertionGuidance);
 82	    }
 83	
 84	    // ── ShowReplacementGuidance ──────────────────────────────────────────────────
 85	
 86	    [Fact]
 87	    public void ShowReplacementGuidance_WhenReplacedModsPresent_ReturnsTrue()
 88	    {
 89	        // Arrange
 90	        var vm = Create([Line(DiffChangeType.Replaced)]);
 91	
 92	        // Act & Assert
 93	        Assert.True(vm.ShowReplacementGuidance);
 94	    }
 95	
