 14	using LoadOrderKeeper.ViewTexts;
 15	
 16	namespace LoadOrderKeeper.ViewModels
 17	{
 18	    public class ConfirmationRequestedEventArgs : EventArgs
 19	    {
 20	        public string Title { get; }
 21	        public string Message { get; }
 22	        public ConfirmationIcon Icon { get; }
 23	        public ConfirmationButton Buttons { get; }
 24	        public ConfirmationResult Result { get; set; }
 25	
 26	        public ConfirmationRequestedEventArgs(string title, string message, ConfirmationIcon icon = ConfirmationIcon.Warning, ConfirmationButton buttons = ConfirmationButton.YesNo)
 27	        {
 28	            Title = title;
 29	            Message = message;
 30	            Icon = icon;
 31	            Buttons = buttons;
 32	            Result = ConfirmationResult.None;
 33	        }
 34	    }
 35	
 36	    public partial class DiffDialogViewModel : ObservableObject, IDisposable
 37	    {
 38	        private readonly MainViewModel _mainViewModel;
 39	        private readonly ListCollectionView _filteredDiffLines;
 40	        private bool _suppressCollectionNotification;
 41	        private string _lastDiffSignature = string.Empty;
 42	        private bool _isRefreshing;
 43	
 44	        [ObservableProperty]
 45	        private bool _isConfigValid = true;
 46	
 47	        [ObservableProperty]
 48	        private bool _isOperationInProgress;
 49	
 50	        [ObservableProperty]
 51	        private bool _showAllMods = false;
 52	
 53	        public bool ShowOverlay => !IsConfigValid && !IsOperationInProgress;
 54	
 55	        // Add localization texts
 56	        public DiffDialogTexts Texts { get; } = new();
