324	            OnPropertyChanged(nameof(HasReplacedMods));
325	            OnPropertyChanged(nameof(ShowRemovalGuidance));
326	            OnPropertyChanged(nameof(ShowInsertionGuidance));
327	            OnPropertyChanged(nameof(ShowReplacementGuidance));
328	            OnPropertyChanged(nameof(ShowAddedGuidance));
329	            OnPropertyChanged(nameof(ShowNoChangesGuidance));
330	
331	            // Count display strings
332	            OnPropertyChanged(nameof(RemovedModCountText));
333	            OnPropertyChanged(nameof(InsertedModCountText));
334	            OnPropertyChanged(nameof(ReplacedModCountText));
335	            OnPropertyChanged(nameof(AddedModCountText));
336	        }
