364	        private void ReplaceDiffLines(IEnumerable<DiffLineModel> fullLines)
365	        {
366	            _suppressCollectionNotification = true;
367	            try
368	            {
369	                DiffLines.Clear();
370	                foreach (var line in fullLines)
371	                {
372	                    DiffLines.Add(line);
373	                }
374	            }
375	            finally
376	            {
377	                _suppressCollectionNotification = false;
378	            }
379	
380	            ApplyLineNumbers(DiffLines);
381	
382	            // Force property change notifications for all computed properties
383	            UpdateDiffState();
384	        }
