386	        private bool FilterDiffLines(object item)
387	        {
388	            if (item is not DiffLineModel line)
389	            {
390	                return false;
391	            }
392	
393	            if (line.ChangeType == DiffChangeType.Separator)
394	            {
395	                return false;
396	            }
397	
398	            if (ShowAllMods)
399	            {
400	                return true;
401	            }
402	
403	            return line.ChangeType != DiffChangeType.Unchanged;
404	        }
