413	        private static void ApplyLineNumbers(IEnumerable<DiffLineModel> lines)
414	        {
415	            var list = lines as IList<DiffLineModel> ?? lines.ToList();
416	            int maxNumber = list.Count > 0
417	                ? list.Max(l => l.ReferenceNumber ?? l.CurrentNumber ?? 0)
418	                : 0;
419	            int width = Math.Max(3, maxNumber.ToString().Length);
420	            string format = new string('0', width);
421	
422	            foreach (var line in list)
423	            {
424	                int? displayNumber = line.ReferenceNumber ?? line.CurrentNumber;
425	                line.FormattedLineNumber = displayNumber.HasValue
426	                    ? displayNumber.Value.ToString(format)
427	                    : string.Empty;
428	            }
429	        }
